// IconSVG is the action's icon, empty when it has none
func (b BulkAction) IconSVG() template.HTML {
	paths, ok := bulkIcons[b.Icon]
	if !ok {
		return ""
	}
	return template.HTML(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" class="remixicon size-4 shrink-0" aria-hidden="true">` + paths + `</svg>`)
}

// HasBulkIcon reports whether name is a known bulk action icon
func HasBulkIcon(name string) bool {
	_, ok := bulkIcons[name]
	return ok
}
